/// <summary>
/// CB202_SalesQuotaMinMax
/// SA line search class 1st inventory dimension specific otherwise inventDimIdBlank()
/// </summary>
internal final class METAgreementLineSearch
{
    METAgreementLineSearchParameters agreementLineSearchParameters;    

}

Method.Source:
/// <summary>
/// Construct
/// </summary>
/// <param name = "_salesTable"><c>SalesTable</c> record</param>
/// <param name = "_salesLine"><c>SalesLine</c> record</param>
/// <returns>Instance of class <c>METAgreementLineSearch</c></returns>
static METAgreementLineSearch construct(SalesTable  _salesTable,
                                        SalesLine   _salesLine)
{
    if (!_salesTable || !_salesLine)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    METAgreementLineSearchParameters agreementLineSearchParameters = METAgreementLineSearchParameters::construct(_salesLine.ItemId,
                                                                                                                 _salesTable.receiptDate(),
                                                                                                                 _salesTable.custAccount,
                                                                                                                 _salesLine.SalesUnit,
                                                                                                                 _salesLine.inventDim());       

    return METAgreementLineSearch::newFromParameters(agreementLineSearchParameters);
}

/// <summary>
/// Creates a new instance of <c>METAgreementLineSearch</c> class from the parameters.
/// </summary>
/// <param name = "_agreementLineSearchParameters">The parameters for sales agreement line search.</param>
/// <returns>An instance of the sales agreement line search class.</returns>
protected static METAgreementLineSearch newFromParameters(METAgreementLineSearchParameters _agreementLineSearchParameters)
{
    return new METAgreementLineSearch(_agreementLineSearchParameters);
}

/// <summary>
/// New method
/// </summary>
/// <param name = "_agreementLineSearchParameters">The parameters for sales agreement line search.</param>
protected void new(METAgreementLineSearchParameters _agreementLineSearchParameters)
{
    agreementLineSearchParameters = _agreementLineSearchParameters;
}

/// <summary>
/// Run the SA line search
/// </summary>
/// <returns><c>METAgreementLineSearchResult</c> if SA line found; otherwise, null.</returns>
METAgreementLineSearchResult run()
{              
    METAgreementLineSearchResult result;

    // First search for vendor category value commitment
    result = METAgreementLineSearchCommitmentType::construct(CommitmentType::METVendorCategoryProductVolume, agreementLineSearchParameters).search();

    if (result)
    {
        return result;
    }

    // If not found, search for ProductQuantity
    result = METAgreementLineSearchCommitmentType::construct(CommitmentType::ProductQuantity, agreementLineSearchParameters).search();

    if (result)
    {
        return result;
    }

    // If not found, search for ProductVolume
    return METAgreementLineSearchCommitmentType::construct(CommitmentType::ProductVolume, agreementLineSearchParameters).search();
}
